<?php use VazinCMS\Security; ?><section class="title"><div><h1>تیکت‌های پشتیبانی</h1><p>صف مدیریت درخواست‌ها</p></div></section><?php if($error):?><div class="alert"><?=Security::e($error)?></div><?php endif;?><section class="panel"><form class="filters" method="get"><select name="status"><option value="">همه وضعیت‌ها</option><?php foreach(['open'=>'باز','answered'=>'پاسخ داده‌شده','customer_reply'=>'پاسخ مشتری','closed'=>'بسته'] as $v=>$l):?><option value="<?=$v?>" <?=$status===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select><select name="priority"><option value="">همه اولویت‌ها</option><?php foreach(['low'=>'کم','normal'=>'عادی','high'=>'زیاد','urgent'=>'فوری'] as $v=>$l):?><option value="<?=$v?>" <?=$priority===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select><button>فیلتر</button></form></section><section class="split"><div class="panel"><h2>تیکت جدید</h2><form method="post"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><label>مشتری<select name="user_id" required><option value="">انتخاب مشتری</option><?php foreach($clients as $c):?><option value="<?=$c['id']?>"><?=Security::e($c['name'].' — '.$c['email'])?></option><?php endforeach;?></select></label><label>عنوان<input name="subject" required></label><label>اولویت<select name="priority"><option value="normal">عادی</option><option value="low">کم</option><option value="high">زیاد</option><option value="urgent">فوری</option></select></label><label>پیام<textarea name="body" rows="5" required></textarea></label><button>ساخت تیکت</button></form></div><div class="panel"><div class="table"><table><thead><tr><th>#</th><th>عنوان</th><th>مشتری</th><th>اولویت</th><th>وضعیت</th><th>آخرین تغییر</th></tr></thead><tbody><?php foreach($tickets as $t):?><tr><td><?=$t['id']?></td><td><a href="/admin/tickets/<?=$t['id']?>"><?=Security::e($t['subject'])?></a></td><td><?=Security::e((string)$t['customer'])?></td><td><span class="priority <?=$t['priority']?>"><?=Security::e($t['priority'])?></span></td><td><?=Security::e($t['status'])?></td><td><?=Security::e((string)$t['updated_at'])?></td></tr><?php endforeach;?></tbody></table></div></div></section>
